// Node 22. Keep the last event id and send it as Last-Event-ID when you reconnect.
const res = await fetch('https://api.ballotdata.net/v1/stream?subscription=CA%20labor', {
  headers: { Authorization: `Bearer ${process.env.BALLOTDATA_API_KEY}` },
});
const decoder = new TextDecoder();
let buffer = '';
for await (const chunk of res.body) {
  buffer += decoder.decode(chunk, { stream: true });
  let end;
  while ((end = buffer.indexOf('\n\n')) >= 0) {
    const block = buffer.slice(0, end);
    buffer = buffer.slice(end + 2);
    const field = (name) => block.match(new RegExp(`^${name}: (.*)$`, 'm'))?.[1];
    if (field('event') === 'endorsement') console.log(JSON.parse(field('data')));
  }
}

