import os
import requests

res = requests.post(
    "https://api.ballotdata.net/v1/subscriptions",
    json={
        "name": "CA labor",
        "filter": {
            "categories": ["labor"],
            "states": ["CA"]
        }
    },
    headers={"Authorization": f"Bearer {os.environ['BALLOTDATA_API_KEY']}"},
)
res.raise_for_status()
data = res.json()["data"]

